package com.oops.payroll.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

/**
 * Represents a salary record for an employee in a selected month.
 * This class stores the final payroll result generated by the backend.
 */
@Entity
@Table(name = "payroll_records")
public class Payroll {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private int payrollId;
    @ManyToOne
    @JoinColumn(name = "employee_id", nullable = false)
    private Employee employee;
    @Column(name = "pay_period")
    private String month;
    private double basicSalary;
    private double allowances;
    private double overtime;
    private double bonus;
    private double deductions;
    private double netSalary;

    public Payroll() {
    }

    public Payroll(int payrollId, Employee employee, String month,
                   double basicSalary, double allowances, double overtime,
                   double bonus, double deductions, double netSalary) {
        setPayrollId(payrollId);
        this.employee = employee;
        setMonth(month);
        setBasicSalary(basicSalary);
        setAllowances(allowances);
        setOvertime(overtime);
        setBonus(bonus);
        setDeductions(deductions);
        setNetSalary(netSalary);
    }

    public int getPayrollId() {
        return payrollId;
    }

    public void setPayrollId(int payrollId) {
        if (payrollId <= 0) {
            throw new IllegalArgumentException("Payroll ID must be positive.");
        }
        this.payrollId = payrollId;
    }

    public Employee getEmployee() {
        return employee;
    }

    public void setEmployee(Employee employee) {
        if (employee == null) {
            throw new IllegalArgumentException("Employee cannot be null.");
        }
        this.employee = employee;
    }

    public String getMonth() {
        return month;
    }

    public void setMonth(String month) {
        if (month == null || month.trim().isEmpty()) {
            throw new IllegalArgumentException("Month cannot be empty.");
        }
        this.month = month.trim();
    }

    public double getBasicSalary() {
        return basicSalary;
    }

    public void setBasicSalary(double basicSalary) {
        if (basicSalary < 0) {
            throw new IllegalArgumentException("Basic salary cannot be negative.");
        }
        this.basicSalary = basicSalary;
    }

    public double getAllowances() {
        return allowances;
    }

    public void setAllowances(double allowances) {
        if (allowances < 0) {
            throw new IllegalArgumentException("Allowances cannot be negative.");
        }
        this.allowances = allowances;
    }

    public double getOvertime() {
        return overtime;
    }

    public void setOvertime(double overtime) {
        if (overtime < 0) {
            throw new IllegalArgumentException("Overtime cannot be negative.");
        }
        this.overtime = overtime;
    }

    public double getBonus() {
        return bonus;
    }

    public void setBonus(double bonus) {
        if (bonus < 0) {
            throw new IllegalArgumentException("Bonus cannot be negative.");
        }
        this.bonus = bonus;
    }

    public double getDeductions() {
        return deductions;
    }

    public void setDeductions(double deductions) {
        if (deductions < 0) {
            throw new IllegalArgumentException("Deductions cannot be negative.");
        }
        this.deductions = deductions;
    }

    public double getNetSalary() {
        return netSalary;
    }

    public void setNetSalary(double netSalary) {
        if (netSalary < 0) {
            throw new IllegalArgumentException("Net salary cannot be negative.");
        }
        this.netSalary = netSalary;
    }
}
